@Test
public void testWithoutThrown() {
    final Log4j1XmlLayout layout = Log4j1XmlLayout.createLayout(false, true);
    final Log4jLogEvent event = Log4jLogEvent.newBuilder().setLoggerName("a.B").setLevel(Level.INFO).setMessage(new SimpleMessage("Hello, World")).setTimeMillis(System.currentTimeMillis() + 17).build();
    final String result = layout.toSerializable(event);
    final String expected = "<log4j:event logger=\"a.B\" timestamp=\"" + event.getTimeMillis() + "\" level=\"INFO\" thread=\"main\">\r\n" + "<log4j:message><![CDATA[Hello, World]]></log4j:message>\r\n" + "</log4j:event>\r\n\r\n";
    assertEquals(expected, result);
}

@Test
public void testWithPropertiesAndLocationInfo() {
    final Log4j1XmlLayout layout = Log4j1XmlLayout.createLayout(true, true);
    final StringMap contextMap = ContextDataFactory.createContextData(2);
    contextMap.putValue("key1", "value1");
    contextMap.putValue("key2", "value2");
    final Log4jLogEvent event = Log4jLogEvent.newBuilder().setLoggerName("a.B").setLevel(Level.INFO).setMessage(new SimpleMessage("Hello, World")).setTimeMillis(System.currentTimeMillis() + 17).setIncludeLocation(true).setSource(new StackTraceElement("pack.MyClass", "myMethod", "MyClass.java", 17)).setContextData(contextMap).build();
    final String result = layout.toSerializable(event);
    final String expected = "<log4j:event logger=\"a.B\" timestamp=\"" + event.getTimeMillis() + "\" level=\"INFO\" thread=\"main\">\r\n" + "<log4j:message><![CDATA[Hello, World]]></log4j:message>\r\n" + "<log4j:locationInfo class=\"pack.MyClass\" method=\"myMethod\" file=\"MyClass.java\" line=\"17\"/>\r\n" + "<log4j:properties>\r\n" + "<log4j:data name=\"key1\" value=\"value1\"/>\r\n" + "<log4j:data name=\"key2\" value=\"value2\"/>\r\n" + "</log4j:properties>\r\n" + "</log4j:event>\r\n\r\n";
    assertEquals(expected, result);
}

/**
 * Serialize Level.INFO and check against witness.
 *
 * @throws Exception if exception during test.
 */
@Test
public void testSerializeINFO() throws Exception {
    final int[] skip = new int[] {};
    SerializationTestHelper.assertSerializationEquals("target/test-classes/witness/serialization/info.bin", Level.INFO, skip, Integer.MAX_VALUE);
}

/**
 * Deserialize witness and see if resolved to Level.INFO.
 *
 * @throws Exception if exception during test.
 */
@Test
public void testDeserializeINFO() throws Exception {
    final Object obj = SerializationTestHelper.deserializeStream("target/test-classes/witness/serialization/info.bin");
    assertTrue(obj instanceof Level);
    final Level info = (Level) obj;
    assertEquals("INFO", info.toString());
    //
    //  JDK 1.1 doesn't support readResolve necessary for the assertion
    if (!System.getProperty("java.version").startsWith("1.1.")) {
        assertTrue(obj == Level.INFO);
    }
}

/**
 * Tests that a custom level can be serialized and deserialized
 * and is not resolved to a stock level.
 *
 * @throws Exception if exception during test.
 */
@Test
public void testCustomLevelSerialization() throws Exception {
    final CustomLevel custom = new CustomLevel();
    final Object obj = SerializationTestHelper.serializeClone(custom);
    assertTrue(obj instanceof CustomLevel);
    final CustomLevel clone = (CustomLevel) obj;
    assertEquals(Level.INFO.level, clone.level);
    assertEquals(Level.INFO.levelStr, clone.levelStr);
    assertEquals(Level.INFO.syslogEquivalent, clone.syslogEquivalent);
}

