    assertFalse(Level.FATAL.isInRange(Level.DEBUG, Level.DEBUG));
    assertFalse(Level.FATAL.isInRange(Level.TRACE, Level.TRACE));
    assertFalse(Level.FATAL.isInRange(Level.ALL, Level.ALL));
    // Level.ERROR
