    final Stack<Class<?>> reversed = new Stack<>();
    reversed.ensureCapacity(classes.size());
    while (!classes.empty()) {
        reversed.push(classes.pop());
    }
    while (reversed.peek() != StackLocatorUtil.class) {
        reversed.pop();
    }
    // ReflectionUtil
