        expected.set(2014, Calendar.MARCH, 10, 00, 00, 00);
        expected.set(Calendar.MILLISECOND, 0);
        assertEquals(format(expected.getTimeInMillis()), format(actual));
    } finally {
        Locale.setDefault(old);
    }
}

