public void testSocket() throws Exception {
    TestSocketServer testServer;
    ExecutorService executor = null;
    Future<InputStream> futureIn;
    try {
        executor = Executors.newSingleThreadExecutor();
        System.err.println("Initializing server");
        testServer = new TestSocketServer();
        futureIn = executor.submit(testServer);
        //System.err.println("Initializing logger");
        final Logger logger = context.getLogger();
        String message = "Log #1";
        logger.error(message);
        final BufferedReader reader = new BufferedReader(new InputStreamReader(futureIn.get()));
        assertEquals(message, reader.readLine());
        //System.err.println("Closing server");
        closeQuietly(testServer);
        assertTrue("Server not shutdown", testServer.server.isClosed());
        //System.err.println("Sleeping to ensure no race conditions");
        Thread.sleep(1000);
        message = "Log #2";
        try {
            logger.error(message);
            fail("Expected exception not thrown");
        } catch (final AppenderLoggingException e) {
            // An exception is expected.
        }
        message = "Log #3";
        try {
            logger.error(message);
            fail("Expected exception not thrown");
        } catch (final AppenderLoggingException e) {
            // An exception is expected.
        }
    } finally {
        closeQuietly(executor);
    }
}

@Test
public void testReconnect() throws Exception {
    list.clear();
    resolver.ports = new int[] { ports[0] };
    server1 = new TestSocketServer(ports[0]);
    server1.start();
    Thread.sleep(200);
    String message = "Log #1";
    String msg = null;
    for (int i = 0; i < 5; ++i) {
        logger.error(message);
        Thread.sleep(100);
        if (list.size() > 0) {
            msg = list.get(0);
            if (msg != null) {
                break;
            }
        }
    }
    assertNotNull("No message", msg);
    assertEquals(message, msg);
    logger.error(SHUTDOWN);
    server1.join();
    list.clear();
    message = "Log #2";
    boolean exceptionCaught = false;
    for (int i = 0; i < 100; ++i) {
        try {
            logger.error(message);
        } catch (final AppenderLoggingException e) {
            exceptionCaught = true;
            break;
            // System.err.println("Caught expected exception");
        }
    }
    assertTrue("No Exception thrown", exceptionCaught);
    message = "Log #3";
    server1 = new TestSocketServer(ports[0]);
    server1.start();
    Thread.sleep(300);
    msg = null;
    for (int i = 0; i < 5; ++i) {
        logger.error(message);
        Thread.sleep(100);
        if (list.size() > 0) {
            msg = list.get(0);
            if (msg != null) {
                break;
            }
        }
    }
    assertNotNull("No message", msg);
    assertEquals(message, msg);
    logger.error(SHUTDOWN);
    server1.join();
}

@Test
public void testFailover() throws Exception {
    list.clear();
    server1 = new TestSocketServer(ports[0]);
    server2 = new TestSocketServer(ports[1]);
    resolver.ports = ports;
    server1.start();
    server2.start();
    Thread.sleep(100);
    String message = "Log #1";
    String msg = null;
    for (int i = 0; i < 5; ++i) {
        logger.error(message);
        Thread.sleep(100);
        if (list.size() > 0) {
            msg = list.get(0);
            if (msg != null) {
                break;
            }
        }
    }
    assertNotNull("No message", msg);
    assertEquals(message, msg);
    server1.shutdown();
    server1.join();
    list.clear();
    message = "Log #2";
    for (int i = 0; i < 5; ++i) {
        logger.error(message);
        Thread.sleep(100);
        if (list.size() > 0) {
            msg = list.get(0);
            if (msg != null) {
                break;
            }
        }
    }
    assertNotNull("No message", msg);
    assertEquals(message, msg);
    server2.shutdown();
    server2.join();
}

