    final String[] options = { "%level", PatternParser.NO_CONSOLE_NO_ANSI + "=false, " + PatternParser.DISABLE_ANSI + "=false, " + "DEBUG=" + colorName + ", CUSTOM1=" + colorName };
    final HighlightConverter converter = HighlightConverter.newInstance(null, options);
    Assert.assertNotNull(converter);
    Assert.assertNotNull(converter.getLevelStyle(Level.INFO));
    Assert.assertNotNull(converter.getLevelStyle(Level.DEBUG));
    Assert.assertNotNull(converter.getLevelStyle(Level.forName("CUSTOM1", 412)));
    Assert.assertNull(converter.getLevelStyle(Level.forName("CUSTOM2", 512)));
    assertArrayEquals(new byte[] { 27, '[', '3', '4', 'm', 'D', 'E', 'B', 'U', 'G', 27, '[', 'm' }, toFormattedCharSeq(converter, Level.DEBUG).toString().getBytes());
    assertArrayEquals(new byte[] { 27, '[', '3', '2', 'm', 'I', 'N', 'F', 'O', 27, '[', 'm' }, toFormattedCharSeq(converter, Level.INFO).toString().getBytes());
    assertArrayEquals(new byte[] { 27, '[', '3', '4', 'm', 'C', 'U', 'S', 'T', 'O', 'M', '1', 27, '[', 'm' }, toFormattedCharSeq(converter, Level.forName("CUSTOM1", 412)).toString().getBytes());
    assertArrayEquals(new byte[] { 'C', 'U', 'S', 'T', 'O', 'M', '2' }, toFormattedCharSeq(converter, Level.forName("CUSTOM2", 512)).toString().getBytes());
}

