@Test
public void testReconfiguration() throws Exception {
    final Configuration oldConfig = context.getConfiguration();
    final int MONITOR_INTERVAL_SECONDS = 5;
    final File file = new File(CONFIG);
    final long orig = file.lastModified();
    final long newTime = orig + 10000;
    assertTrue("setLastModified should have succeeded.", file.setLastModified(newTime));
    TimeUnit.SECONDS.sleep(MONITOR_INTERVAL_SECONDS + 1);
    for (int i = 0; i < 17; ++i) {
        logger.info("Reconfigure");
    }
    int loopCount = 0;
    Configuration newConfig;
    do {
        Thread.sleep(100);
        newConfig = context.getConfiguration();
    } while (newConfig == oldConfig && loopCount++ < 5);
    assertNotSame("Reconfiguration failed", newConfig, oldConfig);
}

@Test
// parameter set to null to allow garbage collection
@SuppressWarnings("UnusedAssignment")
public void testParametersAreNotLeaked() throws Exception {
    final CountDownLatch latch = new CountDownLatch(1);
    final ReusableMessage message = (ReusableMessage) ReusableMessageFactory.INSTANCE.newMessage("foo {}", new ParameterObject("paramValue", latch));
    // Large enough for the parameters, but smaller than the default reusable array size.
    message.swapParameters(new Object[5]);
    final GarbageCollectionHelper gcHelper = new GarbageCollectionHelper();
    gcHelper.run();
    try {
        assertTrue("Parameter should have been garbage collected", latch.await(30, TimeUnit.SECONDS));
    } finally {
        gcHelper.close();
    }
}

@Test
public void testMultipleClassLoaders() throws Exception {
    final Class<?> logging1 = loader1.loadClass(PKG + ".a.Logging1");
    final Field field1 = logging1.getDeclaredField("logger");
    final Logger logger1 = (Logger) ReflectionUtil.getStaticFieldValue(field1);
    assertNotNull(logger1);
    final Class<?> logging2 = loader2.loadClass(PKG + ".b.Logging2");
    final Field field2 = logging2.getDeclaredField("logger");
    final Logger logger2 = (Logger) ReflectionUtil.getStaticFieldValue(field2);
    assertNotNull(logger2);
    final Class<?> logging3 = loader3.loadClass(PKG + ".c.Logging3");
    final Field field3 = logging3.getDeclaredField("logger");
    final Logger logger3 = (Logger) ReflectionUtil.getStaticFieldValue(field3);
    assertNotNull(logger3);
    assertNotSame(logger1.getContext(), logger2.getContext());
    assertNotSame(logger1.getContext(), logger3.getContext());
    assertNotSame(logger2.getContext(), logger3.getContext());
}

